#include <bits/stdc++.h>
using namespace std;

const long long MOD1 = 1e9+7;
const long long MOD2 = 998244353;
const int MAX_DEPTH = 7;
const long long BASE_NUM = 1000000;

long long max_number, order_idx;
int total_answer;
int prefix_sum_array[MAX_DEPTH];
vector<int> digit_collection[MAX_DEPTH];

void build_sequence(int start_value, int level) {
    order_idx++;
    digit_collection[level].push_back(((order_idx - start_value) % MOD2 + MOD2) % MOD2);
    prefix_sum_array[level] = (prefix_sum_array[level] + digit_collection[level].back()) % MOD1;
    if (level == 6) return;
    for (int digit = 0; digit <= 9; digit++) {
        build_sequence(start_value * 10 + digit, level + 1);
    }
}

void traverse_number(long long x) {
    if (x > max_number) return;
    if (x * BASE_NUM + BASE_NUM - 1 <= max_number && x * BASE_NUM * 10 > max_number) {
        long long saved_order = order_idx;
        for (int depth = 0, factor = 1; depth <= 6; depth++, factor *= 10) {
            int size = (int)digit_collection[depth].size();
            int diff = (int)(((saved_order - x * factor) % MOD2 + MOD2) % MOD2);
            int position = (int)(lower_bound(digit_collection[depth].begin(), digit_collection[depth].end(), (int)(MOD2 - diff)) - digit_collection[depth].begin());
            total_answer = (total_answer + 1LL * diff * size + prefix_sum_array[depth]) % MOD1;
            total_answer = (total_answer - 1LL * MOD2 * (size - position) % MOD1 + MOD1) % MOD1;
            order_idx += size;
        }
        return;
    }
    order_idx++;
    total_answer = (total_answer + ((order_idx - x) % MOD2 + MOD2) % MOD2) % MOD1;
    for (int digit = 0; digit <= 9; digit++) {
        traverse_number(x * 10 + digit);
    }
}

int main() {
    cin >> max_number;
    order_idx = 0;
    build_sequence(0, 0);
    for (int i = 0; i <= 6; i++) {
        sort(digit_collection[i].begin(), digit_collection[i].end());
    }
    order_idx = 0;
    for (int i = 1; i <= 9; i++) {
        traverse_number(i);
    }
    cout << total_answer << "\n";
    return 0;
}
